package com.cbs.fx;
import static com.cbs.fx.FxTradeModels.*;
import com.cbs.access.*;
import com.cbs.accounts.*;
import com.cbs.accounting.*;
import com.cbs.customers.CustomerService;
import com.cbs.reference.ReferenceDataService;
import com.cbs.tenancy.*;
import com.cbs.tenancy.TenantModels.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;
@Service
@ConditionalOnProperty(name="cbs.tenancy.enabled",havingValue="true",matchIfMissing=true)
public class FxTradeService {
 private static final JsonMapper JSON=JsonMapper.builder().build();private final JdbcTemplate jdbc;private final TenantRepository tenants;private final FxService rates;private final AccountService accounts;private final CustomerService customers;private final BankOperationStore positions;private final BankJournalStore bankJournals;private final JournalService journals;private final ReferenceDataService reference;private final BankFxStore store;private final BankDatabaseProvisioner databases;private final TransactionTemplate tx;
 public FxTradeService(JdbcTemplate jdbc,TenantRepository tenants,FxService rates,AccountService accounts,CustomerService customers,BankOperationStore positions,BankJournalStore bankJournals,JournalService journals,ReferenceDataService reference,BankFxStore store,BankDatabaseProvisioner databases,PlatformTransactionManager manager){this.jdbc=jdbc;this.tenants=tenants;this.rates=rates;this.accounts=accounts;this.customers=customers;this.positions=positions;this.bankJournals=bankJournals;this.journals=journals;this.reference=reference;this.store=store;this.databases=databases;this.tx=new TransactionTemplate(manager);}
 public Map<String,Object> list(Actor actor,UUID bankId,int limit,int offset){AccessService.admin(actor);AccessService.page(limit,offset);return tx.execute(t->{var bank=tenants.get(bankId,true);return Map.of("version",bank.version(),"businessDate",reference.read(bank).businessDate(),"storageReady",List.of(Status.ACTIVE,Status.SUSPENDED).contains(bank.status())&&store.ready(bank),"items",jdbc.query("SELECT id,payload,completed,failure_code,EXISTS(SELECT 1 FROM platform.fx_trade r WHERE r.original_id=t.id) reversed FROM platform.fx_trade t WHERE tenant_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->Map.of("id",r.getObject(1,UUID.class),"batch",JSON.readTree(r.getString(2)),"completed",r.getBoolean(3),"failureCode",Objects.toString(r.getString(4),""),"reversed",r.getBoolean(5)),bankId,limit,offset),"total",jdbc.queryForObject("SELECT count(*) FROM platform.fx_trade WHERE tenant_id=?",Long.class,bankId));});}
 public void prepare(Actor actor,UUID bankId){AccessService.admin(actor);tx.executeWithoutResult(t->{var bank=tenants.get(bankId,true);if(bank.status()!=Status.ACTIVE)throw error("LEDGER_BANK_NOT_ACTIVE");var schema=databases.upgradeOwned(bank.id(),bank.databaseBinding().databaseReference());tenants.audit(actor,bankId,"FX_STORAGE_PREPARED",bank.version(),bank.status(),bank.status(),"Prepared approved bank FX storage",null,null,Map.of("schemaVersion",schema));});}
 private AccountModels.Definition account(Tenant bank,UUID id){OperationService.requireIdle(jdbc,id);var row=accounts.current(bank.id(),id);var a=row.definition();if(!row.delivery().equals("APPLIED")||a.state()!=AccountModels.State.ACTIVE)throw error("FUNDING_ACCOUNT_NOT_READY");accounts.requireMatching(bank,a);customers.requireEligible(bank,a.customerId());return a;}
 private void positionLedger(Tenant bank,AccountModels.Definition account,UUID id){if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.journal_ledger l JOIN platform.journal_delivery j ON j.request_id=l.request_id WHERE l.ledger_id=? AND NOT j.completed)",Boolean.class,id))throw error("LEDGER_JOURNAL_PENDING");if(!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.ledger_registry l JOIN platform.chart_account c ON c.id=l.chart_account_id WHERE l.tenant_id=? AND l.id=? AND l.currency=? AND l.legal_entity_id=? AND c.category='EQUITY')",Boolean.class,bank.id(),id,account.terms().currency(),account.legalEntityId()))throw error("FX_POSITION_LEDGER_INVALID");if(!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.fx_position WHERE ledger_id=?)",Boolean.class,id)&&bankJournals.hasBalance(bank,id))throw error("FX_POSITION_NOT_EMPTY");}
 public Batch preview(Actor actor,UUID bank,Trade input){AccessService.admin(actor);return tx.execute(t->validate(tenants.get(bank,true),input,UUID.randomUUID()));}
 public Batch validate(Tenant bank,Trade input,UUID id){DayCloseService.requireOpen(jdbc,bank.id());if(bank.version()!=input.expectedVersion())throw error("STALE_VERSION");if(!store.ready(bank))throw error("FX_STORAGE_REQUIRED");if(!reference.read(bank).businessDate().equals(input.businessDate()))throw error("JOURNAL_BUSINESS_DATE_INVALID");var quote=rates.quote(bank,new FxModels.QuoteInput(input.rateId(),input.side(),input.sourceAmount()));if(new BigDecimal(quote.targetAmount()).compareTo(new BigDecimal(input.expectedTargetAmount()))!=0)throw error("FX_QUOTE_CHANGED");return build(bank,id,null,account(bank,input.sourceAccountId()),account(bank,input.targetAccountId()),quote,input.sourcePositionLedger(),input.targetPositionLedger(),input.reason());}
 private Batch build(Tenant bank,UUID id,UUID original,AccountModels.Definition source,AccountModels.Definition target,FxModels.Quote quote,UUID sourcePosition,UUID targetPosition,String reason){if(source.id().equals(target.id())||!source.customerId().equals(target.customerId())||!source.legalEntityId().equals(target.legalEntityId())||!source.terms().currency().equals(quote.sourceCurrency())||!target.terms().currency().equals(quote.targetCurrency()))throw error("FX_ACCOUNT_SCOPE_INVALID");FxValuationService.requireTrade(jdbc,bank,source.legalEntityId(),quote.sourceCurrency(),quote.targetCurrency(),sourcePosition,targetPosition,quote.sourceAmount(),quote.targetAmount(),quote.businessDate());positionLedger(bank,source,sourcePosition);positionLedger(bank,target,targetPosition);var from=positions.position(bank,source);var to=positions.position(bank,target);if(!from.reconciled()||!to.reconciled())throw error("FUNDING_UNRECONCILED");if(new BigDecimal(from.withdrawable()).compareTo(new BigDecimal(quote.sourceAmount()))<0)throw error("INSUFFICIENT_AVAILABLE_BALANCE");TransactionLimits.check(jdbc,bank.id(),quote.sourceCurrency(),original==null?"FX_CONVERSION":"FX_REVERSAL",quote.businessDate(),new BigDecimal(quote.sourceAmount()));
  UUID sourceId=UUID.nameUUIDFromBytes((id+"/source").getBytes(StandardCharsets.UTF_8)),targetId=UUID.nameUUIDFromBytes((id+"/target").getBytes(StandardCharsets.UTF_8));
  var sourceJournal=journal(bank,sourceId,source.legalEntityId(),quote.sourceCurrency(),quote.businessDate(),List.of(new JournalModels.Line(from.ledgerId(),JournalModels.Side.DEBIT,quote.sourceAmount()),new JournalModels.Line(sourcePosition,JournalModels.Side.CREDIT,quote.sourceAmount())),reason);
  var targetJournal=journal(bank,targetId,target.legalEntityId(),quote.targetCurrency(),quote.businessDate(),List.of(new JournalModels.Line(targetPosition,JournalModels.Side.DEBIT,quote.targetAmount()),new JournalModels.Line(to.ledgerId(),JournalModels.Side.CREDIT,quote.targetAmount())),reason);
  return new Batch(id,bank.id(),original,source,target,quote,sourceJournal,targetJournal);
 }
 private JournalModels.Entry journal(Tenant bank,UUID id,UUID entity,String currency,java.time.LocalDate date,List<JournalModels.Line> lines,String reason){var change=new JournalModels.Change(bank.version(),"FX-"+id,reason,date,entity,currency,lines,null,reason);journals.validateFx(bank,change);return new JournalModels.Entry(id,bank.id(),change.reference(),reason,date,entity,currency,lines,null);}
 public Batch validateReversal(Tenant bank,Reversal input,UUID id){DayCloseService.requireOpen(jdbc,bank.id());if(bank.version()!=input.expectedVersion())throw error("STALE_VERSION");if(!reference.read(bank).businessDate().equals(input.businessDate()))throw error("JOURNAL_BUSINESS_DATE_INVALID");var rows=jdbc.queryForList("SELECT payload::text FROM platform.fx_trade WHERE tenant_id=? AND id=? AND completed AND original_id IS NULL",String.class,bank.id(),input.originalId());if(rows.isEmpty()||jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.fx_trade WHERE original_id=?)",Boolean.class,input.originalId()))throw error("FX_REVERSAL_INVALID");var original=JSON.readValue(rows.getFirst(),Batch.class);var q=original.quote();var reversed=new FxModels.Quote(q.rateId(),q.side()==FxModels.Side.BANK_BUYS_BASE?FxModels.Side.BANK_SELLS_BASE:FxModels.Side.BANK_BUYS_BASE,q.targetCurrency(),q.sourceCurrency(),q.targetAmount(),q.sourceAmount(),q.appliedRate(),q.roundingMode(),"0",input.businessDate(),q.expiresAt());return build(bank,id,original.id(),account(bank,original.target().id()),account(bank,original.source().id()),reversed,original.targetJournal().lines().getFirst().ledgerId(),original.sourceJournal().lines().getLast().ledgerId(),input.reason());}
 public Map<String,Object> values(Batch b){return Map.of("quote",b.quote(),"sourceAccount",b.source().accountNumber(),"targetAccount",b.target().accountNumber(),"sourceJournal",b.sourceJournal(),"targetJournal",b.targetJournal(),"originalId",b.originalId()==null?"":b.originalId().toString());}
 public void enqueue(Actor actor,UUID bankId,Trade input,UUID id,String maker){AccessService.admin(actor);var bank=tenants.get(bankId,true);save(actor,bank,validate(bank,input,id),maker,input.reason());}
 public void reverse(Actor actor,UUID bankId,Reversal input,UUID id,String maker){AccessService.admin(actor);var bank=tenants.get(bankId,true);save(actor,bank,validateReversal(bank,input,id),maker,input.reason());}
 private void save(Actor actor,Tenant bank,Batch b,String maker,String reason){jdbc.update("INSERT INTO platform.fx_trade(id,tenant_id,original_id,source_account,target_account,business_date,source_currency,source_amount,payload,maker_subject,reviewer_issuer,reviewer_subject,correlation_id) VALUES (?,?,?,?,?,?,?,?,?::jsonb,?,?,?,?)",b.id(),bank.id(),b.originalId(),b.source().id(),b.target().id(),b.quote().businessDate(),b.quote().sourceCurrency(),new BigDecimal(b.quote().sourceAmount()),JSON.writeValueAsString(b),maker,actor.issuer(),actor.subject(),actor.correlationId());
  for(var j:List.of(b.sourceJournal(),b.targetJournal())){jdbc.update("INSERT INTO platform.journal_delivery(request_id,approval_id,tenant_id,reference,payload,maker_subject,reviewer_issuer,reviewer_subject,correlation_id) VALUES (?,?,?,?,?::jsonb,?,?,?,?)",j.id(),b.id(),bank.id(),j.reference(),JSON.writeValueAsString(j),maker,actor.issuer(),actor.subject(),actor.correlationId());for(var l:j.lines())jdbc.update("INSERT INTO platform.journal_ledger VALUES (?,?)",j.id(),l.ledgerId());jdbc.update("INSERT INTO platform.fx_posting VALUES (?,?)",j.id(),b.id());}
  for(var ledger:List.of(b.sourceJournal().lines().getLast().ledgerId(),b.targetJournal().lines().getFirst().ledgerId()))jdbc.update("INSERT INTO platform.fx_position(ledger_id,tenant_id) VALUES (?,?) ON CONFLICT DO NOTHING",ledger,bank.id());
  tenants.change(bank,bank.status(),bank.displayName(),bank.defaultLanguage());tenants.audit(actor,bank.id(),b.originalId()==null?"FX_CONVERSION_APPROVED":"FX_REVERSAL_APPROVED",bank.version()+1,bank.status(),bank.status(),reason,null,null,values(b));
 }
 public List<UUID> pending(){return jdbc.queryForList("SELECT id FROM platform.fx_trade WHERE NOT completed ORDER BY last_attempt_at NULLS FIRST,created_at LIMIT 20",UUID.class);}
 public void retry(Actor actor,UUID bank,UUID id){AccessService.admin(actor);if(!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.fx_trade WHERE id=? AND tenant_id=? AND reviewer_issuer=?)",Boolean.class,id,bank,actor.issuer()))throw error("APPROVAL_NOT_FOUND");deliver(id);}
 public void deliver(UUID id){tx.executeWithoutResult(t->{var ids=jdbc.queryForList("SELECT tenant_id FROM platform.fx_trade WHERE id=?",UUID.class,id);if(ids.isEmpty())return;var bank=tenants.get(ids.getFirst(),true);var jobs=jdbc.query("SELECT * FROM platform.fx_trade WHERE id=? AND NOT completed FOR UPDATE",(r,n)->new Dispatch(JSON.readValue(r.getString("payload"),Batch.class),r.getString("maker_subject"),r.getString("reviewer_issuer"),r.getString("reviewer_subject"),r.getObject("correlation_id",UUID.class)),id);if(jobs.isEmpty())return;var job=jobs.getFirst();String failure=null;try{if(!store.posted(bank,id)){if(bank.status()!=Status.ACTIVE)throw error("LEDGER_BANK_NOT_ACTIVE");accounts.requireMatching(bank,job.batch().source());accounts.requireMatching(bank,job.batch().target());customers.requireEligible(bank,job.batch().source().customerId());}store.post(bank,job);}catch(TenantException e){failure=e.code();}
  jdbc.update("UPDATE platform.fx_trade SET attempts=attempts+1,last_attempt_at=clock_timestamp(),failure_code=?,completed=? WHERE id=?",failure,failure==null,id);jdbc.update("UPDATE platform.journal_delivery SET completed=?,failure_code=?,completed_at=CASE WHEN ? THEN clock_timestamp() ELSE NULL END WHERE request_id IN (SELECT journal_id FROM platform.fx_posting WHERE trade_id=?)",failure==null,failure,failure==null,id);if(failure==null)tenants.audit(new Actor(job.issuer(),job.checker(),true,job.correlationId()),bank.id(),"FX_POSTED",bank.version(),bank.status(),bank.status(),"Posted both FX legs atomically",null,null,Map.of("tradeId",id));});}
 private static TenantException error(String code){return new TenantException(409,code,"FX conversion requires attention");}
}
